using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace CFEditor {
sealed class PreampEngineDouble {
 public int Bank=2,Channel=1;public string Model="Chime";public int Boost=128,Enabled=1;
 public int getIntParamValue(string group,string key){switch(key){case "currentAmpBank":return Bank;case "currentAmpChannel":return Channel;case "Boost":return Boost;case "BoostEnable":return Enabled;}throw new Exception("unexpected native read "+key);}
 public string getStringParamValue(string group,string key){return Model;}
}
static class NativePreampChecks {
 sealed class Journal:IPreampJournal {public PreampPendingSave Pending;public PreampPendingSave Load(){return Pending;}public void Save(PreampPendingSave p){Pending=p;}}
 sealed class Receiver:IAssetExchange {
  public byte Index=4;public uint Revision=1;public PreampSettings Value=new PreampSettings{Type=3,Tone=.7f,Level=1.2f};public PreampSettings Saved;public int Sets,Saves,SetRequests,RejectSets;public uint RejectStatus=2;public bool TimeoutNextSet;public Action OnReject;public bool AllModels;public bool BusyRead,MetadataBusy=true,MetadataEmpty;public readonly int[] MetadataReads=new int[2];
  static void Put(byte[] b,int n,uint v){Buffer.BlockCopy(BitConverter.GetBytes(v),0,b,n,4);}
  public Task<byte[]> Exchange(byte[] packet,int timeout,CancellationToken cancel){cancel.ThrowIfCancellationRequested();var q=AssetWire.Decode(packet);byte[] data;
   if(q.Opcode==1){data=new byte[20];Put(data,4,13u|(AllModels?AssetWire.AllAmpPreamp|AssetWire.SafeControlOwner:0u));Put(data,8,256);Put(data,12,5);Put(data,16,2);}
   else if(q.Opcode==5){if(timeout!=30000)throw new Exception("Preamp metadata uses a short/unbounded scan deadline");if(q.Slot<3||q.Slot>4)throw new Exception("unexpected metadata slot");MetadataReads[q.Slot-3]++;if(q.Slot==4&&(MetadataBusy||MetadataEmpty)){data=new byte[8];Put(data,0,MetadataEmpty?7u:1u);}else{data=new byte[204];Put(data,4,7);Put(data,8,77);Put(data,12,7772);Buffer.BlockCopy(new AssetInfo{Name="Receiver NAM "+(q.Slot-2),InputDb=-12}.Encode(),0,data,20,184);}}
   else{uint status=q.Opcode==9&&BusyRead?1u:0u;if(q.Opcode==10){SetRequests++;if(TimeoutNextSet){TimeoutNextSet=false;throw new TimeoutException("injected missing SET acknowledgement");}if(RejectSets>0){RejectSets--;Revision++;status=RejectStatus;if(OnReject!=null)OnReject();}else if(q.Slot!=Index||q.Number!=Revision)status=2;else{Value=PreampSettings.Decode(q.Data);Revision++;Sets++;}}else if(q.Opcode==11){if(q.Slot!=Index||q.Number!=Revision)status=2;else{Saved=Value.Copy();Saves++;}}else if(q.Opcode!=9&&q.Opcode!=12)throw new Exception("unexpected opcode");
    data=new byte[44];Put(data,0,status);Put(data,4,Index);Put(data,8,Revision);Buffer.BlockCopy((q.Opcode==12?Saved:Value).Encode(),0,data,12,32);
   }return Task.FromResult(AssetWire.Encode(new AssetMessage{Product=q.Product,Session=q.Opcode==1?q.Transaction:q.Session,Transaction=q.Transaction,Number=q.Number,Slot=q.Slot,Opcode=(byte)(q.Opcode|64),Data=data}));
  }
 }
 const BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static void Set(object o,string field,object v){o.GetType().GetField(field,Flags).SetValue(o,v);}static object Call(object o,string name,params object[] args){try{return o.GetType().GetMethod(name,Flags).Invoke(o,args);}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Need(bool b,string name){if(!b)throw new Exception(name);}static bool Refused(Action run){try{run();return false;}catch(IOException){return true;}}
 public static void Run(string path){var old=SynchronizationContext.Current;SynchronizationContext.SetSynchronizationContext(new ShutdownContext());try{
  var checks=new List<string>();var receiver=new Receiver();var journal=new Journal();var client=new PreampClient(receiver,2424833,journal);client.Connect(400,CancellationToken.None).GetAwaiter().GetResult();var engine=new PreampEngineDouble();var backend=new NativeBackend();Set(backend,"wrapper",typeof(PreampEngineDouble));Set(backend,"native",engine);Set(backend,"connected",true);Set(backend,"synced",true);Set(backend,"product",2424833);Set(backend,"preampClient",client);Set(backend,"preampReady",true);Set(backend,"preampModelSupported",true);
  Call(backend,"Receive","CatalystGroupAmp","graphSlot_AssetEngineID","Chime");var observed=new Dictionary<string,object>();backend.Changed+=(g,p,v)=>{if(g=="CFPreamp")observed[p]=v;};Call(backend,"ReadCFPreamp");Need(!PreampCapability.Available(backend),"unconfirmed NAM slot enables custom pedal");
  var names=new Dictionary<string,object>();backend.Changed+=(g,p,v)=>{if(g=="CFAssets")names[p]=v;};Call(backend,"ReadCFAssetNames");Need(Convert.ToBoolean(names["NAM1Known"])&&!Convert.ToBoolean(names["NAM2Known"]),"busy metadata presented as confirmed");Need(PreampCapability.Available(backend)&&Convert.ToInt32(observed["level"])==60&&Convert.ToInt32(observed["tone"])==70,"capability/read scaling");receiver.MetadataBusy=false;Call(backend,"ReadCFAssetNames");Call(backend,"ReadCFAssetNames");Need(receiver.MetadataReads.SequenceEqual(new[]{1,2})&&Convert.ToString(names["NAM2"])=="Receiver NAM 2"&&Convert.ToBoolean(names["NAM2Known"]),"confirmed metadata re-read or busy name never recovered");checks.Add("real metadata names cached within a session; only an unconfirmed busy slot is queried again");
  Call(backend,"SetCFPreamp",new Binding("CFPreamp",Catalog.Int("level","Level",0,100),true,"Chime"),75);Need(receiver.Sets==1&&receiver.Value.Level==1.5f,"manual level scale");checks.Add("confirmed capability enables controls; wire values map to UI percentages");
  var captured=(PreampSnapshot)Call(backend,"CaptureCFPreamp");Need(captured.Index==4&&Math.Abs(captured.Settings.Drive-128f/255)<1e-6&&captured.Settings.Enabled,"native boost authority");
  receiver.Value=new PreampSettings();receiver.Revision++;Call(backend,"SaveCFPreamp",captured);Need(receiver.Saves==1&&receiver.Saved.Type==3&&receiver.Saved.Level==1.5f&&journal.Pending==null,"native receipt reload lost edit");checks.Add("native preset save/reload followed by captured preamp persistence, with native Drive/ON authoritative");
  captured=(PreampSnapshot)Call(backend,"CaptureCFPreamp");int requests=receiver.SetRequests;receiver.RejectSets=1;Call(backend,"SaveCFPreamp",captured);Need(receiver.SetRequests==requests+2&&receiver.Saves==2&&receiver.Saved.Type==3&&receiver.Saved.Level==1.5f&&journal.Pending==null,"explicit revision conflict not refreshed exactly once");checks.Add("post-native-save revision conflict refreshes the same preset/model; exactly one persistent SAVE");
  captured=(PreampSnapshot)Call(backend,"CaptureCFPreamp");requests=receiver.SetRequests;receiver.RejectSets=10;Need(Refused(()=>Call(backend,"SaveCFPreamp",captured))&&receiver.SetRequests==requests+4&&receiver.Saves==2&&journal.Pending==null,"conflict retry unbounded or persisted without confirmation");receiver.RejectSets=0;checks.Add("repeated revision conflicts stop after four volatile SET attempts without any persistent SAVE");
  Call(backend,"ReadCFPreamp");captured=(PreampSnapshot)Call(backend,"CaptureCFPreamp");requests=receiver.SetRequests;receiver.RejectSets=1;receiver.OnReject=()=>engine.Model="Clean";Need(Refused(()=>Call(backend,"SaveCFPreamp",captured))&&receiver.SetRequests==requests+1&&receiver.Saves==2,"model change was rebased onto another amp");receiver.OnReject=null;engine.Model="Chime";checks.Add("model changes during post-save retry stop before another SET or SAVE");
  Call(backend,"ReadCFPreamp");captured=(PreampSnapshot)Call(backend,"CaptureCFPreamp");requests=receiver.SetRequests;receiver.TimeoutNextSet=true;bool timeout=false;try{Call(backend,"SaveCFPreamp",captured);}catch(TimeoutException){timeout=true;}Need(timeout&&receiver.SetRequests==requests+1&&receiver.Saves==2&&journal.Pending==null,"lost SET reply was blindly repeated");checks.Add("missing volatile SET acknowledgement is not retried or converted into a persistent SAVE");Call(backend,"ReadCFPreamp");
  receiver.Index=5;receiver.Revision++;engine.Channel=2;Need(Refused(()=>Call(backend,"SaveCFPreamp",captured))&&receiver.Saves==2,"wrong destination save");checks.Add("preset changed during save cannot receive another preset's preamp");
  engine.Channel=0;receiver.Index=12;receiver.Revision++;Call(backend,"ReadCFPreamp");Need(((PreampSnapshot)Call(backend,"CaptureCFPreamp")).Index==12,"manual SDK/native mapping");checks.Add("manual channel SDK 0 maps to native sidecar 12");
  receiver.Revision++;int before=receiver.Sets;Need(Refused(()=>Call(backend,"SetCFPreamp",new Binding("CFPreamp",Catalog.Int("tone","Tone",0,100),true,"Chime"),80))&&before==receiver.Sets,"stale UI edit accepted");checks.Add("stale UI context rejected before applying a control");
  Call(backend,"ReadCFPreamp");engine.Model="Clean";Need(Refused(()=>Call(backend,"SetCFPreamp",new Binding("CFPreamp",Catalog.Int("type","Preamp",0,3),true,"Chime"),1))&&before==receiver.Sets,"wrong model edit accepted");checks.Add("old model controls cannot edit the newly selected model");
  Call(backend,"Receive","CatalystGroupAmp","graphSlot_AssetEngineID","Clean");Need(!PreampCapability.Available(backend)&&Call(backend,"CaptureCFPreamp")==null,"stock amp claims custom pedal DSP");Call(backend,"ReadCFPreamp");Need(Convert.ToInt32(observed["type"])==0,"stock amp displays unavailable pedal");Call(backend,"Receive","CatalystGroupAmp","graphSlot_AssetEngineID","Chime 2");Need(PreampCapability.Available(backend),"NAM 2 lacks confirmed pedal control");checks.Add("stock amps retain factory Boost; extended pedal controls and labels are enabled only for the implemented NAM path");
  receiver.BusyRead=true;Need(Refused(()=>Call(backend,"ReadCFPreamp"))&&!PreampCapability.Available(backend),"busy preset leaves stale controls enabled");receiver.BusyRead=false;Call(backend,"ReadCFPreamp");Need(PreampCapability.Available(backend),"temporary busy permanently disables controls");checks.Add("temporary preset BUSY disables stale controls and recovers on a later read without reconnecting the SDK");
  ((bool[])backend.GetType().GetField("cfNamesRead",Flags).GetValue(backend))[1]=false;receiver.MetadataEmpty=true;Call(backend,"ReadCFAssetNames");Need(!PreampCapability.Available(backend)&&Convert.ToInt32(observed["type"])==0&&Call(backend,"CaptureCFPreamp")==null,"empty NAM bank advertises custom pedal on factory fallback");checks.Add("an empty NAM position retains factory processing and never advertises an inactive custom pedal");
  var allReceiver=new Receiver{AllModels=true,MetadataEmpty=true,MetadataBusy=false,Index=12};var allJournal=new Journal();var allClient=new PreampClient(allReceiver,2424833,allJournal);allClient.Connect(800,CancellationToken.None).GetAwaiter().GetResult();Need(allClient.AllAmpPreamp,"all-model capability was not negotiated");Set(backend,"preampClient",allClient);Call(backend,"ReadCFPreamp");
  foreach(string model in new[]{"Clean","Chime","Boutique","Crunch","Dynamic","Hi Gain","Clean 2","Chime 2","Boutique 2","Crunch 2","Dynamic 2","Hi Gain 2"}){
   engine.Model=model;Call(backend,"Receive","CatalystGroupAmp","graphSlot_AssetEngineID",model);Need(PreampCapability.Available(backend),"negotiated pedal disabled on "+model);
   foreach(int type in new[]{1,2,3})Call(backend,"SetCFPreamp",new Binding("CFPreamp",Catalog.Int("type","Preamp",0,3),true,model),type);
  }
  captured=(PreampSnapshot)Call(backend,"CaptureCFPreamp");Call(backend,"SaveCFPreamp",captured);Need(allReceiver.Sets==37&&allReceiver.Saves==1&&allReceiver.Saved.Type==3,"stock-model pedal changes/persistence failed");checks.Add("explicit all-model firmware capability enables EP/808/SD1 on all twelve OEM models, including empty NAM fallback, and persists once");
  engine.Model="Unknown model";Call(backend,"Receive","CatalystGroupAmp","graphSlot_AssetEngineID",engine.Model);Need(!PreampCapability.Available(backend)&&Call(backend,"CaptureCFPreamp")==null,"unknown model advertises custom processing");checks.Add("unknown models remain disabled; old firmware never advertises stock-model support");
  Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path)));File.WriteAllText(path,new JavaScriptSerializer().Serialize(new{passed=true,USB_opened=false,SDK_loaded=false,device_enumeration=false,native_driver_called=false,checks=checks.ToArray()}));
 }finally{SynchronizationContext.SetSynchronizationContext(old);}}
}
